INSERT INTO `pages` VALUES (5,'Journal','journal','','','','published','inner',NULL,6,'2026-05-08 03:23:14','2026-05-08 03:23:14',NULL),(6,'The Designer','the-designer','<img class=\"alignleft wp-image-1319\" src=\"https://antonioscouture.com/wp-content/uploads/2015/11/designer-746x1024.jpg\" alt=\"designer\" width=\"600\" height=\"823\" /> <p style=\"text-align: justify;\">Ghassan Antonios, a designer, modelist and a couturier, is known for his vision, creativity and attention to detail. His dresses are a unique reflection of his ingenuity and innovation from the creation of the design until the final touches.</p> <p style=\"text-align: justify;\">Born in 1969 in Beirut, Ghassan Antonios studied fashion at College Artistique de La Mode Moderne and worked at prestigious fashion houses in Beirut and Paris. He immersed in the world of Haute Couture and developed a deep understanding of the art. He is an artist who transforms the fabrics into unique pieces of living art, and a modelist that mixes to perfection the complexity of the body, design, fabric and colors.</p> <p style=\"text-align: justify;\">Upon completion of his studies, Ghassan Antonios taught theoretical and practical fashion courses for three years in Beirut and worked as head of atelier at Lebanese Haute Couture houses and private clients throughout the Arab Gulf.</p> <p style=\"text-align: justify;\">Ghassan Antonios founded Antonios Couture in 1999. Since then he has designed and presented Bridal and Haute Couture collections at fashion shows in Beirut and Paris.</p> <p style=\"text-align: justify;\">For Ghassan Antonios, The story of a dress starts like a dream. It is the untouchable idea mixed with the precious fabric and passed through the hands of the artisan. That’s how his dresses become a reality – a reality that is like a dream.</p> <p style=\"text-align: justify;\">Ghassan Antonios’ diverse background and his wide knowledge of various cultures around the world, allowed his creation and style to reach out to clients from the Arab Gulf, USA, Germany, England and Japan.</p>','','','published','inner',NULL,5,'2026-05-08 03:23:14','2026-05-08 03:23:14',NULL),(7,'Contact','contact','<h5>For any info, Contact:</h5> <a href=\"info@antonioscouture.com\">info@antonioscouture.com</a> <h5>Contact Informations</h5>','','','published','inner',NULL,4,'2026-05-08 03:23:15','2026-05-08 03:23:15',NULL),(8,'News & Events','news-events','<p>News and announcements from Antonios Couture. Use the admin CMS to add content — the WordPress export did not include a standalone page for this URL.</p>','','','published','inner',NULL,11,'2026-05-08 03:23:15','2026-05-08 03:23:15',NULL),(10,'Terms & Conditions','terms-and-conditions','<h1>Terms & Conditions</h1>\n<p>This page describes the general terms that apply when you use our website and purchase products from us. By placing an order or browsing our site, you agree to review and follow these terms.</p>\n<p>The information here is provided for general guidance only and does not replace professional legal advice where needed. We may update this page from time to time; continued use of the site after changes constitutes acceptance of the revised terms.</p>\n<p>If you have questions, please <a href=\"/contact-us\">contact us</a> and we will be happy to help.</p>','Terms & Conditions — general information.','terms, and, conditions','published','',NULL,500,'2026-05-11 03:57:30','2026-05-11 03:57:30',NULL),(11,'Refund and Returns Policy','refund-and-returns-policy','<h1>Refund and Returns Policy</h1>\n<p>We want you to be satisfied with your purchase. This policy outlines how returns, exchanges, and refunds are handled in typical situations.</p>\n<p>Eligibility, time limits, and condition of items may apply. Please retain proof of purchase and follow any return instructions provided with your order or by our support team.</p>\n<p>Specific cases (made-to-measure items, final sale, or promotional goods) may be treated differently; details will be confirmed at checkout or by customer service.</p>\n<p>If you have questions, please <a href=\"/contact-us\">contact us</a> and we will be happy to help.</p>','Refund and Returns Policy — general information.','refund, and, returns, policy','published','',NULL,500,'2026-05-11 03:57:30','2026-05-11 03:57:30',NULL),(12,'Privacy Policy','privacy-policy','<h1>Privacy Policy</h1>\n<p>We respect your privacy. This policy explains what personal information we may collect when you use our website or shop with us, how we use it, and the choices available to you.</p>\n<p>We process data only as needed to operate our store, fulfil orders, communicate with you, and comply with applicable law. We do not sell your personal information.</p>\n<p>You may contact us to exercise applicable rights (such as access or correction) depending on your jurisdiction.</p>\n<p>If you have questions, please <a href=\"/contact-us\">contact us</a> and we will be happy to help.</p>','Privacy Policy — general information.','privacy, policy','published','',NULL,500,'2026-05-11 03:57:30','2026-05-11 03:57:30',NULL),(13,'When Will My Order Arrive?','when-will-my-order-arrive','<h1>When Will My Order Arrive?</h1>\n<p>Delivery times depend on product availability, processing, and the shipping method you select at checkout.</p>\n<p>Once your order ships, you should receive confirmation with tracking details where available. Carriers may update estimated delivery dates while your package is in transit.</p>\n<p>If your order seems delayed beyond the estimated window, please reach out with your order number so we can investigate.</p>\n<p>If you have questions, please <a href=\"/contact-us\">contact us</a> and we will be happy to help.</p>','When Will My Order Arrive? — general information.','when, will, my, order, arrive','published','',NULL,500,'2026-05-11 03:57:30','2026-05-11 03:57:30',NULL),(14,'FAQs','faqs','<h1>FAQs</h1>\n<p>Below are answers to common questions about ordering, sizing, shipping, and account access.</p>\n<p>Ordering: add items to your cart, proceed to checkout, and complete payment using the options shown. You will receive an email confirmation after a successful order.</p>\n<p>Account: you can register or sign in to track orders, manage addresses, and use your wishlist. Use the links under “My Account” in the footer for quick access.</p>\n<p>If you have questions, please <a href=\"/contact-us\">contact us</a> and we will be happy to help.</p>','FAQs — general information.','faqs','published','',NULL,500,'2026-05-11 03:57:30','2026-05-11 03:57:30',NULL);
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
